//! Cross-implementation check: the program's math must reproduce lib/markets/test-vectors.json,
//! which is generated by the TypeScript implementation.

mod common;

use anchor_lang::prelude::Pubkey;
use plain_markets::math;
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::str::FromStr;

const VECTORS: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../../lib/markets/test-vectors.json"));

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}
fn unhex(s: &str) -> [u8; 32] {
    let mut out = [0u8; 32];
    for i in 0..32 {
        out[i] = u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).unwrap();
    }
    out
}
fn u64s(v: &Value) -> u64 {
    v.as_str().unwrap().parse().unwrap()
}
fn opt(v: &Value) -> Option<u64> {
    v.as_str().map(|s| s.parse().unwrap())
}

#[test]
fn entitlement_vectors() {
    let v: Value = serde_json::from_str(VECTORS).unwrap();
    for c in v["coupon"].as_array().unwrap() {
        let got = math::coupon_per_unit(
            u64s(&c["face"]),
            c["rateBps"].as_u64().unwrap() as u16,
            c["frequency"].as_u64().unwrap() as u8,
        );
        assert_eq!(got, opt(&c["perUnit"]), "coupon {c}");
    }
    for c in v["price"].as_array().unwrap() {
        let got = math::price_per_unit(u64s(&c["face"]), c["priceBps"].as_u64().unwrap() as u16);
        assert_eq!(got, opt(&c["perUnit"]), "price {c}");
    }
    for c in v["final"].as_array().unwrap() {
        let got = math::final_per_unit(
            u64s(&c["face"]),
            c["priceBps"].as_u64().unwrap() as u16,
            c["rateBps"].as_u64().unwrap() as u16,
            c["frequency"].as_u64().unwrap() as u8,
        );
        assert_eq!(got, opt(&c["perUnit"]), "final {c}");
    }
    for c in v["partial"].as_array().unwrap() {
        let got = math::partial_redeem_units(u64s(&c["units"]), c["redeemBps"].as_u64().unwrap() as u16);
        assert_eq!(got, opt(&c["redeemUnits"]), "partial {c}");
    }
}

#[test]
fn merkle_vectors() {
    let v: Value = serde_json::from_str(VECTORS).unwrap();
    for c in v["nodes"].as_array().unwrap() {
        let h = math::node_hash(&unhex(c["a"].as_str().unwrap()), &unhex(c["b"].as_str().unwrap()));
        assert_eq!(hex(&h), c["hash"].as_str().unwrap());
    }
    for t in v["trees"].as_array().unwrap() {
        let name = t["name"].as_str().unwrap();
        let action = Pubkey::from_str(t["action"].as_str().unwrap()).unwrap();
        let holdings: Vec<(Pubkey, u64)> = t["holdings"]
            .as_array()
            .unwrap()
            .iter()
            .map(|h| (Pubkey::from_str(h["holder"].as_str().unwrap()).unwrap(), u64s(&h["units"])))
            .collect();
        let tree = common::Tree::new(action, holdings);

        let sorted: Vec<String> = tree.holdings.iter().map(|h| h.0.to_string()).collect();
        let expected_sorted: Vec<String> =
            t["sortedHolders"].as_array().unwrap().iter().map(|s| s.as_str().unwrap().to_string()).collect();
        assert_eq!(sorted, expected_sorted, "{name}: ordering");

        let leaves: Vec<String> = tree.levels[0].iter().map(|l| hex(l)).collect();
        let expected_leaves: Vec<String> =
            t["leaves"].as_array().unwrap().iter().map(|s| s.as_str().unwrap().to_string()).collect();
        assert_eq!(leaves, expected_leaves, "{name}: leaves");
        assert_eq!(hex(&tree.root()), t["root"].as_str().unwrap(), "{name}: root");
        assert_eq!(tree.total(), u64s(&t["totalUnits"]), "{name}: total");

        // Every TS proof verifies with the on-chain verifier and equals the Rust builder's proof.
        let root = unhex(t["root"].as_str().unwrap());
        for (holder, proof) in t["proofs"].as_object().unwrap() {
            let pk = Pubkey::from_str(holder).unwrap();
            let proof: Vec<[u8; 32]> = proof.as_array().unwrap().iter().map(|p| unhex(p.as_str().unwrap())).collect();
            assert_eq!(proof, tree.proof(&pk), "{name}: proof for {holder}");
            let leaf = math::leaf_hash(&action.to_bytes(), &pk.to_bytes(), tree.units(&pk));
            assert!(math::verify_proof(leaf, &proof, &root), "{name}: verify {holder}");
            assert!(
                !math::verify_proof(math::leaf_hash(&action.to_bytes(), &pk.to_bytes(), tree.units(&pk) + 1), &proof, &root),
                "{name}: inflated units must fail"
            );
        }

        let json = t["snapshot"]["json"].as_str().unwrap();
        assert_eq!(hex(&Sha256::digest(json.as_bytes())), t["snapshot"]["sha256"].as_str().unwrap());
    }
}
